// ---------- Utilities ----------
const $ = id => document.getElementById(id);
const fmt = n => Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const historyKey = 'arbCalculatorHistory_v1';

// ---------- Dynamic UI: create fields based on mode ----------
function buildOddsInputs(mode) {
    const container = $('oddsGrid');
    container.innerHTML = '';
    const count = Number(mode);
    for (let i = 1; i <= count; i++) {
        const div = document.createElement('div');
        div.innerHTML = `
          <label class="small" for="odd_${i}">Odd ${i}</label>
          <input id="odd_${i}" type="number" step="0.01" min="1" placeholder="e.g. 2.10">
        `;
        container.appendChild(div);
    }
    // small accessibility/spacing filler
    for (let i = count + 1; i <= 3; i++) {
        if (container.children.length < 3) {
            const filler = document.createElement('div');
            filler.innerHTML = `<div style="height:1px"></div>`;
            container.appendChild(filler);
        }
    }
}

// ---------- Calculation logic (works for 2/3/4) ----------
function readOdds() {
    const mode = Number($('mode').value);
    const odds = [];
    for (let i = 1; i <= mode; i++) {
        const el = $('odd_' + i);
        if (!el) continue;
        const val = parseFloat(el.value);
        if (!isNaN(val) && val > 1) odds.push(val);
    }
    return odds;
}

function calculate(odds, stake) {
    // odds: array, stake: number
    // returns object with impliedSum, stakes array, payout, profit, roiPercent
    const impliedSum = odds.reduce((s, o) => s + (1 / o), 0);
    const result = { impliedSum };
    if (isNaN(stake) || stake <= 0 || odds.length < 2) {
        result.ok = false; return result;
    }
    if (impliedSum < 1) {
        const stakes = odds.map(o => stake * ((1 / o) / impliedSum));
        // payout approximated from first leg
        const payout = stakes[0] * odds[0];
        const profit = payout - stake;
        const roi = (profit / stake) * 100;
        result.ok = true;
        result.stakes = stakes;
        result.payout = payout;
        result.profit = profit;
        result.roi = roi;
    } else {
        result.ok = false;
    }
    return result;
}

// ---------- UI Update ----------
function refreshUI() {
    const stake = parseFloat($('stake').value);
    const odds = readOdds();
    const out = calculate(odds, stake);
    $('impliedSum').textContent = odds.length ? out.impliedSum ? out.impliedSum.toFixed(4) : '—' : '—';
    $('overroundPercent').textContent = odds.length ? ((out.impliedSum - 1) * 100).toFixed(2) + '%' : '—';

    const betsContainer = $('betsContainer');
    betsContainer.innerHTML = '';
    if (out.ok) {
        // show stakes per option and expected return per outcome
        out.stakes.forEach((s, i) => {
            const div = document.createElement('div');
            div.className = 'bet';
            div.innerHTML = `<div>
                             <div><b>Option ${i + 1}</b> <small class="muted">(@ ${odds[i]})</small></div>
                             <div class="muted small">Stake</div>
                           </div>
                           <div style="text-align:right">
                             <div><b>${fmt(s)}</b></div>
                             <div class="muted small">Return ${fmt(s * odds[i])}</div>
                           </div>`;
            betsContainer.appendChild(div);
        });

        $('statusBox').className = 'status ok';
        $('statusBox').textContent = 'Arbitrage Found';
        $('guaranteedPayout').textContent = fmt(out.payout);
        $('profitValue').textContent = fmt(out.profit) + ` (${out.roi.toFixed(2)}%)`;
    } else {
        $('statusBox').className = 'status bad';
        $('statusBox').textContent = odds.length >= 2 ? 'No Arbitrage (sum ≥ 1)' : 'Enter at least 2 odds';
        $('guaranteedPayout').textContent = '—';
        $('profitValue').textContent = '—';

        // clear bets area placeholders
        if (odds.length >= 2) {
            for (let i = 0; i < odds.length; i++) {
                const div = document.createElement('div');
                div.className = 'bet';
                div.innerHTML = `<div><b>Option ${i + 1}</b></div><div style="text-align:right"><div class="muted">—</div></div>`;
                betsContainer.appendChild(div);
            }
        }
    }
}

// ---------- History handling ----------
function saveCalculation() {
    const stake = parseFloat($('stake').value);
    const odds = readOdds();
    const out = calculate(odds, stake);
    if (!out.ok) { showPopup('No arbitrage to save or invalid inputs.'); return; }
    const history = JSON.parse(localStorage.getItem(historyKey) || '[]');
    history.unshift({
        date: (new Date()).toISOString(),
        mode: Number($('mode').value),
        odds,
        stake,
        stakes: out.stakes,
        profit: out.profit,
        roi: out.roi
    });
    // cap history to 200
    if (history.length > 200) history.pop();
    localStorage.setItem(historyKey, JSON.stringify(history));
    showPopup('Saved calculation to history.');
}

function renderHistory() {
    const list = $('historyList');
    const history = JSON.parse(localStorage.getItem(historyKey) || '[]');
    if (!history.length) {
        list.innerHTML = '<div class="muted">No saved calculations yet.</div>';
        return;
    }
    const html = history.map((h, idx) => {
        const d = new Date(h.date).toLocaleString();
        return `<div class="history-item">
                  <div style="display:flex;justify-content:space-between">
                    <div><b>${d}</b><div class="muted">Mode: ${h.mode}-way • Stake ${fmt(h.stake)}</div></div>
                    <div style="text-align:right"><b>${fmt(h.profit)}</b><div class="muted">${h.roi.toFixed(2)}% ROI</div></div>
                  </div>
                  <div class="muted" style="margin-top:8px">Odds: ${h.odds.join(', ')}<br>
                    Stakes: ${h.stakes.map(s => fmt(s)).join(' • ')}</div>
                </div>`;
    }).join('');
    list.innerHTML = html;
}

function clearHistory() {
    if (!confirm('Clear all saved calculations?')) return;
    localStorage.removeItem(historyKey);
    renderHistory();
}

function exportHistoryCSV() {
    const history = JSON.parse(localStorage.getItem(historyKey) || '[]');
    if (!history.length) { showPopup('No history to export'); return; }
    const rows = [
        ['date', 'mode', 'odds', 'stake', 'stakes', 'profit', 'roi']
    ];
    history.forEach(h => {
        rows.push([h.date, h.mode, `"${h.odds.join(';')}"`, h.stake, `"${h.stakes.map(s => s.toFixed(2)).join(';')}"`, h.profit.toFixed(2), h.roi.toFixed(2)]);
    });
    const csv = rows.map(r => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'arb_history.csv'; document.body.appendChild(a);
    a.click(); a.remove(); URL.revokeObjectURL(url);
}

// ---------- Popup Notification ----------
function showPopup(message) {
    const popup = document.getElementById('popupNotification');
    popup.textContent = message;
    popup.style.display = 'block';
    popup.classList.add('show');
    if (window._popupTimeout) clearTimeout(window._popupTimeout);
    window._popupTimeout = setTimeout(() => {
        popup.classList.remove('show');
        popup.style.display = 'none';
    }, 5000);
}

// ---------- event wiring ----------
(function init() {
    // initial build
    buildOddsInputs($('mode').value);

    // mode change
    $('mode').addEventListener('change', e => {
        buildOddsInputs(e.target.value);
    });

    // dynamic inputs: delegate changes to recalc
    document.body.addEventListener('input', (ev) => {
        const id = ev.target.id || '';
        if (id.startsWith('odd_') || id === 'stake') {
            // small debounce
            if (window._calcTimeout) clearTimeout(window._calcTimeout);
            window._calcTimeout = setTimeout(() => refreshUI(), 160);
        }
    });

    // calculate button
    $('calcBtn').addEventListener('click', refreshUI);

    // save/clear
    $('saveBtn').addEventListener('click', saveCalculation);
    $('clearBtn').addEventListener('click', () => {
        for (let i = 1; i <= 4; i++) { const el = $('odd_' + i); if (el) el.value = ''; }
        $('stake').value = ''; refreshUI();
        showPopup('Cleared inputs.');
    });

    // example selector
    $('example').addEventListener('change', (e) => {
        const val = e.target.value;
        if (!val) return;
        try {
            const obj = JSON.parse(val);
            $('mode').value = obj.mode;
            buildOddsInputs(obj.mode);
            setTimeout(() => { // set after inputs created
                obj.odds.forEach((o, i) => { const el = $('odd_' + (i + 1)); if (el) el.value = o; });
                $('stake').value = obj.stake;
                refreshUI();
            }, 30);
        } catch (err) { }
    });

    // about modal
    const aboutModal = $('aboutModal'), aboutBtn = $('aboutBtn'), aboutClose = $('aboutClose');
    aboutBtn.addEventListener('click', () => { aboutModal.style.display = 'flex'; aboutModal.setAttribute('aria-hidden', 'false'); });
    aboutClose.addEventListener('click', () => { aboutModal.style.display = 'none'; aboutModal.setAttribute('aria-hidden', 'true'); });
    aboutModal.addEventListener('click', (ev) => { if (ev.target === aboutModal) { aboutModal.style.display = 'none'; aboutModal.setAttribute('aria-hidden', 'true'); } });

    // history modal
    const historyModal = $('historyModal'), historyBtn = $('historyBtn'), historyClose = $('historyClose');
    historyBtn.addEventListener('click', () => { renderHistory(); historyModal.style.display = 'flex'; historyModal.setAttribute('aria-hidden', 'false'); });
    historyClose.addEventListener('click', () => { historyModal.style.display = 'none'; historyModal.setAttribute('aria-hidden', 'true'); });
    historyModal.addEventListener('click', (ev) => { if (ev.target === historyModal) { historyModal.style.display = 'none'; historyModal.setAttribute('aria-hidden', 'true'); } });

    // history actions
    $('clearHistoryBtn').addEventListener('click', clearHistory);
    $('exportBtn').addEventListener('click', exportHistoryCSV);

    // initial refresh
    refreshUI();
})();